/// Resolve all unresolved Dart imports in the workspace.
/// Called once per parse cycle in post_parse_sequence.
pub fn resolve_dart_imports(db: &Db, workspace_root: &Path) -> Result<usize> {
    let unresolved = db.unresolved_dart_imports()?;
    if unresolved.is_empty() {
        return Ok(0);
    }

    // Build file path → file_id lookup from DB
    let all_files = db.all_files()?;
    let path_to_id: HashMap<&str, i64> = all_files.iter()
        .map(|f| (f.path.as_str(), f.id))
        .collect();

    // Build package map from pubspec.yaml files
    let pkg_map = DartPackageMap::build(workspace_root, ...);

    // Also build file_id → path for relative import resolution
    let id_to_path: HashMap<i64, &str> = all_files.iter()
        .map(|f| (f.id, f.path.as_str()))
        .collect();

    let mut resolved_count = 0;
    for (import_id, file_id, imported_path) in &unresolved {
        let resolved_path = if imported_path.starts_with("package:") {
            // package:arrow_options/models/foo.dart
            // → strip "package:", split on first '/'
            // → (package_name, subpath) = ("arrow_options", "models/foo.dart")
            // → look up package_name in pkg_map → "options/lib/"
            // → join: "options/lib/models/foo.dart"
            resolve_package_uri(imported_path, &pkg_map)
        } else if imported_path.ends_with(".dart")
            && !imported_path.starts_with("dart:") {
            // Relative import: resolve against importing file's directory
            resolve_relative_import(imported_path, *file_id, &id_to_path)
        } else {
            // dart:core, dart:async etc — SDK imports, skip
            None
        };

        if let Some(path) = resolved_path {
            if let Some(&target_file_id) = path_to_id.get(path.as_str()) {
                db.update_import_resolved_file_id(*import_id, target_file_id)?;
                resolved_count += 1;
            }
        }
    }

    Ok(resolved_count)
}

fn resolve_package_uri(uri: &str, pkg_map: &DartPackageMap) -> Option<String> {
    let rest = uri.strip_prefix("package:")?;
    let (pkg_name, subpath) = rest.split_once('/')?;
    let lib_dir = pkg_map.packages.get(pkg_name)?;
    Some(format!("{}{}", lib_dir, subpath))
}

fn resolve_relative_import(path: &str, file_id: i64, id_to_path: &HashMap<i64, &str>) -> Option<String> {
    let importing_path = id_to_path.get(&file_id)?;
    let parent = Path::new(importing_path).parent()?;
    let resolved = parent.join(path);
    // Normalize (handle ../ etc)
    // Convert back to workspace-relative string
    normalize_path(&resolved)
}
```

